document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll('a[href^="http"]').forEach(function(link){if(link.hostname!==window.location.hostname){link.target="_blank";link.rel="noopener noreferrer"}});document.querySelectorAll('a[href^="#"]').forEach(function(link){link.addEventListener("click",function(event){var target=document.querySelector(link.getAttribute("href"));if(target){event.preventDefault();target.scrollIntoView({behavior:"smooth",block:"start"})}})})});
